B.aym=new A.a5([B.r,"Khet mein nami 42% hai. Agle 4 ghante mein halki barish ki sambhavna hai.",B.q,"\u0916\u0947\u0924 \u092e\u0947\u0902 \u0928\u092e\u0940 42% \u0939\u0948\u0964 \u0905\u0917\u0932\u0947 4 \u0918\u0902\u091f\u094b\u0902 \u092e\u0947\u0902 \u0939\u0932\u094d\u0915\u0940 \u0935\u0930\u094d\u0937\u093e \u0915\u0940 \u0938\u0902\u092d\u093e\u0935\u0928\u093e \u0939\u0948\u0964",B.t,"Soil moisture is 42%. Light rain expected in the next 4 hours.",B.v,"\u09ae\u09be\u099f\u09bf\u09a4\u09c7 \u0986\u09b0\u09cd\u09a6\u09cd\u09b0\u09a4\u09be \u09ea\u09e8%\u0964 \u0986\u0997\u09be\u09ae\u09c0 \u09ea \u0998\u09a3\u09cd\u099f\u09be\u09af\u09bc \u09b9\u09be\u09b2\u0995\u09be \u09ac\u09c3\u09b7\u09cd\u099f\u09bf\u09b0 \u09b8\u09ae\u09cd\u09ad\u09be\u09ac\u09a8\u09be \u09b0\u09af\u09bc\u09c7\u099b\u09c7\u0964",B.w,"\u0a9c\u0aae\u0ac0\u0aa8\u0aae\u0abe\u0a82 \u0aad\u0ac7\u0a9c \u0aea\u0ae8% \u0a9b\u0ac7. \u0a86\u0a97\u0abe\u0aae\u0ac0 \u0aea \u0a95\u0ab2\u0abe\u0a95\u0aae\u0abe\u0a82 \u0ab9\u0ab3\u0ab5\u0abe \u0ab5\u0ab0\u0ab8\u0abe\u0aa6\u0aa8\u0ac0 \u0ab6\u0a95\u0acd\u0aaf\u0aa4\u0abe \u0a9b\u0ac7.",B.x,"\u091c\u092e\u093f\u0928\u0940\u0924 \u0913\u0932\u093e\u0935\u093e \u096a\u0968% \u0906\u0939\u0947. \u092a\u0941\u0922\u0940\u0932 \u096a \u0924\u093e\u0938\u093e\u0902\u0924 \u0939\u0932\u0915\u094d\u092f\u093e \u092a\u093e\u0935\u0938\u093e\u091a\u0940 \u0936\u0915\u094d\u092f\u0924\u093e \u0906\u0939\u0947.",B.y,"\u0c28\u0c47\u0c32\u0c32\u0c4b \u0c24\u0c47\u0c2e 42%. \u0c30\u0c3e\u0c2c\u0c4b\u0c2f\u0c47 4 \u0c17\u0c02\u0c1f\u0c32\u0c4d\u0c32\u0c4b \u0c24\u0c47\u0c32\u0c3f\u0c15\u0c2a\u0c3e\u0c1f\u0c3f \u0c35\u0c30\u0c4d\u0c37\u0c02 \u0c2a\u0c21\u0c47 \u0c05\u0c35\u0c15\u0c3e\u0c36\u0c02 \u0c09\u0c02\u0c26\u0c3f.",B.z,"\u0bae\u0ba3\u0bcd\u0ba3\u0bbf\u0ba9\u0bcd \u0b88\u0bb0\u0baa\u0bcd\u0baa\u0ba4\u0bae\u0bcd 42%. \u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 4 \u0bae\u0ba3\u0bbf \u0ba8\u0bc7\u0bb0\u0ba4\u0bcd\u0ba4\u0bbf\u0bb2\u0bcd \u0bb2\u0bc7\u0b9a\u0bbe\u0ba9 \u0bae\u0bb4\u0bc8\u0b95\u0bcd\u0b95\u0bc1 \u0bb5\u0bbe\u0baf\u0bcd\u0baa\u0bcd\u0baa\u0bc1.",B.A,"\u0645\u0679\u06cc \u0645\u06cc\u06ba \u0646\u0645\u06cc 42 \u0641\u06cc\u0635\u062f \u06c1\u06d2\u06d4 \u0627\u06af\u0644\u06d2 4 \u06af\u06be\u0646\u0679\u0648\u06ba \u0645\u06cc\u06ba \u06c1\u0644\u06a9\u06cc \u0628\u0627\u0631\u0634 \u06a9\u0627 \u0627\u0645\u06a9\u0627\u0646 \u06c1\u06d2\u06d4",B.B,"\u0cae\u0ca3\u0ccd\u0ca3\u0cbf\u0ca8\u0cb2\u0ccd\u0cb2\u0cbf \u0ca4\u0cc7\u0cb5\u0cbe\u0c82\u0cb6 42%. \u0cae\u0cc1\u0c82\u0ca6\u0cbf\u0ca8 4 \u0c97\u0c82\u0c9f\u0cc6\u0c97\u0cb3\u0cb2\u0ccd\u0cb2\u0cbf \u0cb8\u0cbe\u0ca7\u0cbe\u0cb0\u0ca3 \u0cae\u0cb3\u0cc6\u0caf\u0cbe\u0c97\u0cc1\u0cb5 \u0cb8\u0cbe\u0ca7\u0ccd\u0caf\u0ca4\u0cc6\u0caf\u0cbf\u0ca6\u0cc6."],t.C)
