B.avL=new A.a5([B.r,"Voice Saarthi AI",B.q,"\u0935\u0949\u0907\u0938 \u0938\u093e\u0930\u0925\u0940 AI",B.t,"Voice Saarthi AI",B.v,"\u0995\u09c3\u09b7\u09bf \u098f\u0997\u09cd\u09b0\u09cb\u09a8\u09cb\u09ae\u09bf\u09b8\u09cd\u099f \u098f\u0986\u0987 \u09b8\u09b9\u0995\u09be\u09b0\u09c0",B.w,"\u0a95\u0ac3\u0ab7\u0abf \u0a8f\u0a97\u0acd\u0ab0\u0acb\u0aa8\u0acb\u0aae\u0abf\u0ab8\u0acd\u0a9f AI \u0ab8\u0ab9\u0abe\u0aaf\u0a95",B.x,"\u0915\u0943\u0937\u0940 \u0924\u091c\u094d\u091c\u094d\u091e AI \u0938\u0932\u094d\u0932\u093e\u0917\u093e\u0930",B.y,"\u0c15\u0c43\u0c37\u0c3f \u0c05\u0c17\u0c4d\u0c30\u0c4b\u0c28\u0c2e\u0c3f\u0c38\u0c4d\u0c1f\u0c4d AI \u0c05\u0c38\u0c3f\u0c38\u0c4d\u0c1f\u0c46\u0c02\u0c1f\u0c4d",B.z,"\u0bb5\u0bc7\u0bb3\u0bbe\u0ba3\u0bcd \u0ba8\u0bbf\u0baa\u0bc1\u0ba3\u0bb0\u0bcd AI \u0b89\u0ba4\u0bb5\u0bbf\u0baf\u0bbe\u0bb3\u0bb0\u0bcd",B.A,"\u06a9\u0631\u0634\u06cc \u0632\u0631\u0639\u06cc \u0645\u0627\u06c1\u0631 AI \u0645\u0639\u0627\u0648\u0646",B.B,"\u0c95\u0cc3\u0cb7\u0cbf \u0ca4\u0c9c\u0ccd\u0c9e AI \u0cb8\u0cb9\u0cbe\u0caf\u0c95"],t.C)
B.axr=new A.a5([B.r,"Namaste Kisan Bhai! \ud83d\ude4f Main Krishi-Saarthi AI assistant hoon. Aap fasal, mausam, khad ya beemari ke baare me bolkar ya likhkar pooch sakte hain.",B.q,"\u0928\u092e\u0938\u094d\u0924\u0947 \u0915\u093f\u0938\u093e\u0928 \u092d\u093e\u0908! \ud83d\ude4f \u092e\u0948\u0902 \u0915\u0943\u0937\u093f-\u0938\u093e\u0930\u0925\u0940 AI \u0938\u0939\u093e\u092f\u0915 \u0939\u0942\u0901\u0964 \u0906\u092a \u0905\u092a\u0928\u0940 \u092b\u0938\u0932, \u092e\u094c\u0938\u092e, \u0916\u093e\u0926 \u092f\u093e \u092c\u0940\u092e\u093e\u0930\u0940 \u0915\u0947 \u092c\u093e\u0930\u0947 \u092e\u0947\u0902 \u092e\u0941\u091d\u0938\u0947 \u092c\u094b\u0932\u0915\u0930 \u092f\u093e \u0932\u093f\u0916\u0915\u0930 \u092a\u0942\u091b \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964",B.t,"Welcome Farmer! \ud83d\ude4f I am Krishi-Saarthi AI Assistant. You can ask anything about crops, weather, fertilizer, or diseases by speaking or typing.",B.v,"\u09a8\u09ae\u09b8\u09cd\u0995\u09be\u09b0 \u0995\u09c3\u09b7\u0995 \u09ad\u09be\u0987! \u0986\u09ae\u09bf \u0986\u09aa\u09a8\u09be\u09b0 \u0986\u0987\u09b8\u09bf\u098f\u0986\u09b0 \u0995\u09c3\u09b7\u09bf \u09b8\u09b9\u0995\u09be\u09b0\u09c0\u0964 \u0986\u09aa\u09a8\u09be\u09b0 \u09ab\u09b8\u09b2 \u09ac\u09be \u09b0\u09cb\u0997 \u09b8\u09ae\u09cd\u09aa\u09b0\u09cd\u0995\u09c7 \u09af\u09c7 \u0995\u09cb\u09a8\u09cb \u09aa\u09cd\u09b0\u09b6\u09cd\u09a8 \u0995\u09b0\u09c1\u09a8\u0964",B.w,"\u0aa8\u0aae\u0ab8\u0acd\u0a95\u0abe\u0ab0 \u0a96\u0ac7\u0aa1\u0ac2\u0aa4 \u0aae\u0abf\u0aa4\u0acd\u0ab0! \u0ab9\u0ac1\u0a82 \u0aa4\u0aae\u0abe\u0ab0\u0acb ICAR \u0a95\u0ac3\u0ab7\u0abf \u0ab8\u0ab9\u0abe\u0aaf\u0a95 \u0a9b\u0ac1\u0a82. \u0aa4\u0aae\u0abe\u0ab0\u0abe \u0aaa\u0abe\u0a95 \u0a85\u0aa5\u0ab5\u0abe \u0ab0\u0acb\u0a97 \u0ab5\u0abf\u0ab6\u0ac7 \u0a95\u0a82\u0a88\u0aaa\u0aa3 \u0aaa\u0ac2\u0a9b\u0acb.",B.x,"\u0928\u092e\u0938\u094d\u0915\u093e\u0930 \u0936\u0947\u0924\u0915\u0930\u0940 \u0926\u093e\u0926\u093e! \u092e\u0940 \u0924\u0941\u092e\u091a\u093e ICAR \u0915\u0943\u0937\u0940 \u092e\u093e\u0930\u094d\u0917\u0926\u0930\u094d\u0936\u0915 \u0906\u0939\u0947. \u092a\u093f\u0915\u093e\u092c\u0926\u094d\u0926\u0932 \u0915\u093f\u0902\u0935\u093e \u0930\u094b\u0917\u093e\u092c\u0926\u094d\u0926\u0932 \u0915\u093e\u0939\u0940\u0939\u0940 \u0935\u093f\u091a\u093e\u0930\u093e.",B.y,"\u0c28\u0c2e\u0c38\u0c4d\u0c15\u0c3e\u0c30\u0c02 \u0c30\u0c48\u0c24\u0c41 \u0c2e\u0c3f\u0c24\u0c4d\u0c30\u0c2e\u0c3e! \u0c28\u0c47\u0c28\u0c41 \u0c2e\u0c40 ICAR \u0c35\u0c4d\u0c2f\u0c35\u0c38\u0c3e\u0c2f \u0c38\u0c39\u0c3e\u0c2f\u0c15\u0c41\u0c21\u0c3f\u0c28\u0c3f. \u0c2a\u0c02\u0c1f \u0c32\u0c47\u0c26\u0c3e \u0c24\u0c46\u0c17\u0c41\u0c33\u0c4d\u0c32 \u0c17\u0c41\u0c30\u0c3f\u0c02\u0c1a\u0c3f \u0c0f\u0c26\u0c48\u0c28\u0c3e \u0c05\u0c21\u0c17\u0c02\u0c21\u0c3f.",B.z,"\u0bb5\u0ba3\u0b95\u0bcd\u0b95\u0bae\u0bcd \u0bb5\u0bbf\u0bb5\u0b9a\u0bbe\u0baf\u0bbf \u0ba4\u0bcb\u0bb4\u0bb0\u0bc7! \u0ba8\u0bbe\u0ba9\u0bcd \u0b89\u0b99\u0bcd\u0b95\u0bb3\u0bcd ICAR \u0bb5\u0bc7\u0bb3\u0bbe\u0ba3\u0bcd \u0b89\u0ba4\u0bb5\u0bbf\u0baf\u0bbe\u0bb3\u0bb0\u0bcd. \u0b89\u0b99\u0bcd\u0b95\u0bb3\u0bcd \u0baa\u0baf\u0bbf\u0bb0\u0bcd \u0b95\u0bc1\u0bb1\u0bbf\u0ba4\u0bcd\u0ba4\u0bc1 \u0b8e\u0ba4\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b95\u0bc7\u0bb3\u0bc1\u0b99\u0bcd\u0b95\u0bb3\u0bcd.",B.A,"\u0633\u0644\u0627\u0645 \u06a9\u0633\u0627\u0646 \u0628\u06be\u0627\u0626\u06cc! \u0645\u06cc\u06ba \u0622\u067e \u06a9\u0627 \u0632\u0631\u0639\u06cc \u0645\u0639\u0627\u0648\u0646 \u06c1\u0648\u06ba\u06d4 \u0627\u067e\u0646\u06cc \u0641\u0635\u0644 \u06cc\u0627 \u0628\u06cc\u0645\u0627\u0631\u06cc \u06a9\u06d2 \u0628\u0627\u0631\u06d2 \u0645\u06cc\u06ba \u06a9\u0686\u06be \u0628\u06be\u06cc \u067e\u0648\u0686\u06be\u06cc\u06ba\u06d4",B.B,"\u0ca8\u0cae\u0cb8\u0ccd\u0c95\u0cbe\u0cb0 \u0cb0\u0cc8\u0ca4 \u0cae\u0cbf\u0ca4\u0ccd\u0cb0\u0cb0\u0cc7! \u0ca8\u0cbe\u0ca8\u0cc1 \u0ca8\u0cbf\u0cae\u0ccd\u0cae ICAR \u0c95\u0cc3\u0cb7\u0cbf \u0cb8\u0cb9\u0cbe\u0caf\u0c95. \u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0cac\u0cc6\u0cb3\u0cc6 \u0c85\u0ca5\u0cb5\u0cbe \u0cb0\u0ccb\u0c97\u0c97\u0cb3 \u0c95\u0cc1\u0cb0\u0cbf\u0ca4\u0cc1 \u0caf\u0cbe\u0cb5\u0cc1\u0ca6\u0cc7 \u0caa\u0ccd\u0cb0\u0cb6\u0ccd\u0ca8\u0cc6 \u0c95\u0cc7\u0cb3\u0cbf."],t.C)
