B.awo=new A.a5([B.r,"Gehun me peela ratua ka ilaj kya hai?",B.q,"\u0917\u0947\u0939\u0942\u0902 \u092e\u0947\u0902 \u092a\u0940\u0932\u093e \u0930\u0924\u0941\u0906 \u0915\u093e \u0907\u0932\u093e\u091c \u0915\u094d\u092f\u093e \u0939\u0948?",B.t,"What is the treatment for yellow rust in wheat?",B.v,"\u0997\u09ae\u09c7 \u09b9\u09b2\u09c1\u09a6 \u09ae\u09b0\u09bf\u099a\u09be \u09b0\u09cb\u0997 \u09aa\u09cd\u09b0\u09a4\u09bf\u09b0\u09cb\u09a7",B.w,"\u0a98\u0a89\u0a82\u0aae\u0abe\u0a82 \u0aaa\u0ac0\u0ab3\u0abe \u0a97\u0ac7\u0ab0\u0ac1 \u0ab0\u0acb\u0a97\u0aa8\u0ac0 \u0ab8\u0abe\u0ab0\u0ab5\u0abe\u0ab0",B.x,"\u0917\u0935\u094d\u0939\u093e\u0935\u0930\u0940\u0932 \u092a\u093f\u0935\u0933\u093e \u0924\u093e\u0902\u092c\u0947\u0930\u093e \u0930\u094b\u0916\u0923\u094d\u092f\u093e\u091a\u0947 \u0909\u092a\u093e\u092f",B.y,"\u0c17\u0c4b\u0c27\u0c41\u0c2e\u0c32\u0c4b \u0c2a\u0c38\u0c41\u0c2a\u0c41 \u0c24\u0c41\u0c2a\u0c4d\u0c2a\u0c41 \u0c24\u0c46\u0c17\u0c41\u0c32\u0c41 \u0c28\u0c3f\u0c35\u0c3e\u0c30\u0c23",B.z,"\u0b95\u0bcb\u0ba4\u0bc1\u0bae\u0bc8\u0baf\u0bbf\u0bb2\u0bcd \u0bae\u0b9e\u0bcd\u0b9a\u0bb3\u0bcd \u0ba4\u0bc1\u0bb0\u0bc1 \u0ba8\u0bcb\u0baf\u0bcd \u0b95\u0b9f\u0bcd\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bbe\u0b9f\u0bc1",B.A,"\u06af\u0646\u062f\u0645 \u0645\u06cc\u06ba \u0632\u0631\u062f \u06a9\u0646\u06af\u06cc \u06a9\u0627 \u0639\u0644\u0627\u062c",B.B,"\u0c97\u0ccb\u0ca7\u0cbf\u0caf\u0cb2\u0ccd\u0cb2\u0cbf \u0cb9\u0cb3\u0ca6\u0cbf \u0ca4\u0cc1\u0c95\u0ccd\u0c95\u0cc1 \u0cb0\u0ccb\u0c97 \u0ca4\u0ca1\u0cc6\u0c97\u0c9f\u0ccd\u0c9f\u0cc1\u0cb5\u0cbf\u0c95\u0cc6"],t.C)
B.awX=new A.a5([B.r,"Aaj sinchai karni chahiye ya nahi?",B.q,"\u0906\u091c \u0938\u093f\u0902\u091a\u093e\u0908 \u0915\u0930\u0928\u093e \u091a\u093e\u0939\u093f\u090f \u092f\u093e \u0928\u0939\u0940\u0902?",B.t,"Should I irrigate the field today?",B.v,"\u0986\u099c\u0995\u09c7\u09b0 \u09ae\u09be\u09a8\u09cd\u09a1\u09bf \u09a6\u09b0 \u0995\u09a4?",B.w,"\u0a86\u0a9c\u0aa8\u0abe \u0aae\u0abe\u0ab0\u0acd\u0a95\u0ac7\u0a9f \u0aaf\u0abe\u0ab0\u0acd\u0aa1\u0aa8\u0abe \u0aad\u0abe\u0ab5 \u0a95\u0ac7\u0a9f\u0ab2\u0abe?",B.x,"\u0906\u091c\u091a\u0947 \u0915\u0943\u0937\u0940 \u0909\u0924\u094d\u092a\u0928\u094d\u0928 \u092c\u093e\u091c\u093e\u0930 \u092d\u093e\u0935 \u0915\u093e\u092f \u0906\u0939\u0947\u0924?",B.y,"\u0c08\u0c30\u0c4b\u0c1c\u0c41 \u0c2e\u0c3e\u0c30\u0c4d\u0c15\u0c46\u0c1f\u0c4d \u0c27\u0c30\u0c32\u0c41 \u0c0e\u0c32\u0c3e \u0c09\u0c28\u0c4d\u0c28\u0c3e\u0c2f\u0c3f?",B.z,"\u0b87\u0ba9\u0bcd\u0bb1\u0bc8\u0baf \u0b9a\u0ba8\u0bcd\u0ba4\u0bc8 \u0bb5\u0bbf\u0bb2\u0bc8 \u0ba8\u0bbf\u0bb2\u0bb5\u0bb0\u0bae\u0bcd \u0b8e\u0ba9\u0bcd\u0ba9?",B.A,"\u0622\u062c \u0645\u0646\u0688\u06cc \u06a9\u06d2 \u0631\u06cc\u0679 \u06a9\u06cc\u0627 \u06c1\u06cc\u06ba\u061f",B.B,"\u0c87\u0c82\u0ca6\u0cbf\u0ca8 \u0cae\u0cbe\u0cb0\u0cc1\u0c95\u0c9f\u0ccd\u0c9f\u0cc6 \u0ca6\u0cb0\u0c97\u0cb3\u0cc1 \u0cb9\u0cc7\u0c97\u0cbf\u0cb5\u0cc6?"],t.C)
