B.axp=new A.a5([B.r,"Desktop par AI Camera, Voice Copilot aur Bima claims ke liye permissions allow karein.",B.q,"\u0921\u0947\u0938\u094d\u0915\u091f\u0949\u092a \u092a\u0930 AI \u0915\u0948\u092e\u0930\u093e, \u0935\u0949\u092f\u0938 \u091a\u0948\u091f \u0914\u0930 \u092c\u0940\u092e\u093e \u0915\u094d\u0932\u0947\u092e \u0915\u0947 \u0932\u093f\u090f \u0905\u0928\u0941\u092e\u0924\u093f\u092f\u093e\u0902 \u0938\u0915\u094d\u0930\u093f\u092f \u0915\u0930\u0947\u0902\u0964",B.t,"Enable permissions for AI camera, voice copilot, and PMFBY insurance claims.",B.v,"\u098f\u0986\u0987 \u0995\u09cd\u09af\u09be\u09ae\u09c7\u09b0\u09be, \u09ad\u09af\u09bc\u09c7\u09b8 \u099a\u09cd\u09af\u09be\u099f \u0993 \u09ac\u09c0\u09ae\u09be \u09a6\u09be\u09ac\u09bf\u09b0 \u099c\u09a8\u09cd\u09af \u0985\u09a8\u09c1\u09ae\u09a4\u09bf \u09b8\u0995\u09cd\u09b0\u09bf\u09af\u09bc \u0995\u09b0\u09c1\u09a8\u0964",B.w,"AI \u0a95\u0ac7\u0aae\u0ac7\u0ab0\u0abe, \u0ab5\u0acb\u0a87\u0ab8 \u0a9a\u0ac7\u0a9f \u0a85\u0aa8\u0ac7 \u0ab5\u0ac0\u0aae\u0abe \u0aa6\u0abe\u0ab5\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0aaa\u0ab0\u0ab5\u0abe\u0aa8\u0a97\u0ac0\u0a93 \u0ab8\u0a95\u0acd\u0ab7\u0aae \u0a95\u0ab0\u0acb.",B.x,"AI \u0915\u0945\u092e\u0947\u0930\u093e, \u0935\u094d\u0939\u0949\u0908\u0938 \u091a\u0945\u091f \u0906\u0923\u093f \u0935\u093f\u092e\u093e \u0926\u093e\u0935\u094d\u092f\u093e\u0938\u093e\u0920\u0940 \u092a\u0930\u0935\u093e\u0928\u0917\u094d\u092f\u093e \u0938\u0915\u094d\u0937\u092e \u0915\u0930\u093e.",B.y,"AI \u0c15\u0c46\u0c2e\u0c46\u0c30\u0c3e, \u0c35\u0c3e\u0c2f\u0c3f\u0c38\u0c4d \u0c1a\u0c3e\u0c1f\u0c4d \u0c2e\u0c30\u0c3f\u0c2f\u0c41 \u0c2c\u0c40\u0c2e\u0c3e \u0c15\u0c4d\u0c32\u0c46\u0c2f\u0c3f\u0c2e\u0c4d\u200c\u0c32 \u0c15\u0c4b\u0c38\u0c02 \u0c05\u0c28\u0c41\u0c2e\u0c24\u0c41\u0c32\u0c28\u0c41 \u0c2a\u0c4d\u0c30\u0c3e\u0c30\u0c02\u0c2d\u0c3f\u0c02\u0c1a\u0c02\u0c21\u0c3f.",B.z,"AI \u0b95\u0bc7\u0bae\u0bb0\u0bbe, \u0b95\u0bc1\u0bb0\u0bb2\u0bcd \u0b85\u0bb0\u0b9f\u0bcd\u0b9f\u0bc8 \u0bae\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0b95\u0bbe\u0baa\u0bcd\u0baa\u0bc0\u0b9f\u0bcd\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bc1 \u0b85\u0ba9\u0bc1\u0bae\u0ba4\u0bbf\u0b95\u0bb3\u0bc8 \u0b87\u0baf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.",B.A,"AI \u06a9\u06cc\u0645\u0631\u06c1\u060c \u0648\u0627\u0626\u0633 \u0686\u06cc\u0679 \u0627\u0648\u0631 \u0628\u06cc\u0645\u06c1 \u062f\u0639\u0648\u0648\u06ba \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u062c\u0627\u0632\u062a\u06cc\u06ba \u0641\u0639\u0627\u0644 \u06a9\u0631\u06cc\u06ba\u06d4",B.B,"AI \u0c95\u0ccd\u0caf\u0cbe\u0cae\u0cc6\u0cb0\u0cbe, \u0ca7\u0ccd\u0cb5\u0ca8\u0cbf \u0c9a\u0cbe\u0c9f\u0ccd \u0cae\u0ca4\u0ccd\u0ca4\u0cc1 \u0cb5\u0cbf\u0cae\u0cbe \u0c95\u0ccd\u0cb2\u0cc8\u0cae\u0ccd\u200c\u0c97\u0cb3\u0cbf\u0c97\u0cbe\u0c97\u0cbf \u0c85\u0ca8\u0cc1\u0cae\u0ca4\u0cbf\u0c97\u0cb3\u0ca8\u0ccd\u0ca8\u0cc1 \u0cb8\u0c95\u0ccd\u0cb0\u0cbf\u0caf\u0c97\u0cca\u0cb3\u0cbf\u0cb8\u0cbf."],t.C)
